<?php
declare(strict_types=1);
require_once __DIR__ . '/../../helpers/auth.php'; require_once __DIR__ . '/../../models/Attendance.php'; require_once __DIR__ . '/../_json.php'; if (!is_logged_in() || !has_role(['SUPER_ADMIN', 'CHURCH_ADMIN', 'STAFF'])) { json_response(['success' => false, 'message' => 'Forbidden.'], 403); } if ($_SERVER['REQUEST_METHOD'] !== 'POST') { json_response(['success' => false, 'message' => 'POST required.'], 405); } $payload = json_decode((string) file_get_contents('php://input'), true); $payload = is_array($payload) ? $payload : $_POST; try { $id = Attendance::record((int) $payload['session_id'], (int) $payload['member_id'], 'MANUAL', (int) current_user_id()); json_response(['success' => true, 'attendance_id' => $id]); } catch (DomainException $exception) { json_response(['success' => false, 'message' => $exception->getMessage()], 409); } catch (Throwable $exception) { json_response(['success' => false, 'message' => 'Attendance could not be recorded.'], 422); }
